#center_text_column_2 {
display:block;
position:absolute;
left:700px;
top:60px;
width:300px;
height:560px;
max-height:560px;
box-sizing:border-box;
overflow-y:auto;
overflow-x:hidden;
padding:0 10px 12px 0;
text-align:left;
font-family:"Sandoll 미생";
font-size:27px;
}
/* Keep hover descriptions outside the clipped equipment list. */
#center_text_column_2 [tooltip-data]:after,
#center_text_column_2 .tooltip-left:hover:after {
position:fixed;
left:418px;
right:auto !important;
top:60px;
bottom:auto;
margin:0;
max-height:560px;
overflow-y:auto;
}
